$capture = new Monolog\Handler\TestHandler;
$monolog = new Monolog\Logger('fixture', [$capture]);
$logger = new Illuminate\Log\Logger($monolog, app('events'));
app()->instance(Psr\Log\LoggerInterface::class, $logger);
$handler = app(Illuminate\Contracts\Debug\ExceptionHandler::class);
$exceptions = new Illuminate\Foundation\Configuration\Exceptions($handler);
$exceptions->level(RuntimeException::class, 'critical');
$e = new RuntimeException('fixture');
$handler->report($e);
$r = $handler->render(Illuminate\Http\Request::create('/api', server: ['HTTP_ACCEPT' => 'application/json']), $e);
echo $capture->getRecords()[0]->level->name.':'.$r->getStatusCode();
